        J.glide(line, line + dir * 140 + Vector3.new(0, 40, 0), 2.2, dir)
        return
    end
    local p = root.Position
    local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
    J.glide(p, p + look * 110 + Vector3.new(0, 40, 0), 2.2, look)
end
function J.land(site, svc)
    local ap = D.AP.List and D.AP.List[site]
    if not ap or not ap.Runways then LOG("no runway", site) return false end
    local rw = J.rwFor(site, lp:GetAttribute("ClearedAirport") == site and lp:GetAttribute("ClearedRunway") or nil)
    local dir = J.nameDir(rw.Name) or J.dirOf(rw.Heading)
    local touch = J.rwStart(rw, dir) + dir * 60
    local pre = touch - dir * 700 + Vector3.new(0, 110, 0)
    J.place(pre, dir, dir * 60)
    local held = RunService.Heartbeat:Connect(function() J.place(pre, dir, dir * 60) end)
    task.wait(0.3)
    if svc == "GoalService" then
        local okc = J.clear("AtcLanding", "Land", 3)
        local cleared = lp:GetAttribute("ClearedRunway")
        LOG("landing clearance", okc, cleared)
        if okc and cleared and cleared ~= "" and cleared ~= rw.Name then
            rw = J.rwFor(site, cleared)
            dir = J.nameDir(cleared) or dir
            touch = J.rwStart(rw, dir) + dir * 60
        end
    end
    held:Disconnect()
    local start = touch - dir * 170 + Vector3.new(0, 26, 0)
    J.glide(pre, start, math.max(1, (start - pre).Magnitude / 180), start - pre)
    J.glide(start, touch, J.glide_s or 3, dir)
    J.place(touch + dir * 2, dir, dir * 15)
    task.wait(0.4)
    M.fire(svc, svc == "GoalService" and "Landed" or "Touchdown", 3)
    return true
end
function J.bestPlane()
    local lic = tonumber(lp:GetAttribute("License")) or 1
    local o = M.json("Owned")
    local best, bp
    if type(o) == "table" then
        for _, id in ipairs(o) do
            local c = D.CR.ById and D.CR.ById[id]
            if c and c.Plane and not J.badPlane[id] and (tonumber(c.License) or 1) <= lic and (not best or (tonumber(c.Price) or 0) > bp) then best, bp = id, tonumber(c.Price) or 0 end
        end
    end
    return best or lp:GetAttribute("Car") or D.CR.FirstPlane
end
function J.board()
    if J.seated() then return true end
    local car = J.car()
    if not car or (J.isTest() == false and J.takeTries ~= nil) then
        if not J.isTest() then
            local tried = {}
            for _, id in ipairs({ J.bestPlane(), lp:GetAttribute("Car"), D.CR.FirstPlane }) do
                if id and not tried[id] and not J.badPlane[id] then
                    tried[id] = true
                    local bay = U and U.bayOf(id)
                    local rr = M.root()
                    if bay and rr and id ~= lp:GetAttribute("Car") then
                        rr.CFrame = CFrame.new(bay + Vector3.new(0, 4, 0))
                        task.wait(1.2)
                    end
                    local r = M.call("MyCarsService", "Take", id)
                    LOG("take plane", id, type(r) == "table" and tostring(r.Ok) or tostring(r))
                    local t0 = os.clock()
                    while not J.seated() and os.clock() - t0 < 2.5 do task.wait(0.1) end
                    if J.seated() then return true end
                end
            end
        end
        car = J.car()
        if not car then return false end
    end
    local pr
    for _, d in ipairs(car:GetDescendants()) do if d:IsA("ProximityPrompt") and d.Enabled then pr = d break end end
    if not pr then return false end
    local pp = pr.Parent:IsA("Attachment") and pr.Parent.WorldPosition or pr.Parent.Position
    local r = M.root()
    if r then r.CFrame = CFrame.new(pp + Vector3.new(0, 2, 3)) end
    task.wait(0.35)
    if typeof(fireproximityprompt) == "function" then pcall(fireproximityprompt, pr) end
    local t0 = os.clock()
    while not J.seated() and os.clock() - t0 < 3 do task.wait(0.1) end
    return J.seated()
end
J.SUPPORT = { Plane = true, Drive = true, Wait = true, Takeoff = true, Fly = true, Pass = true, Dust = true, Act = true, Vehicle = true, Hover = true, Settle = true }
function J.hold(pos, look, secs, leg)
    local t0 = os.clock()
    local c = RunService.Heartbeat:Connect(function() J.place(pos, look, Vector3.zero) end)
    while RUNNING and os.clock() - t0 < secs and J.leg() == leg and J.state() == "Active" do task.wait(0.1) end
    c:Disconnect()
end
function J.step()
    local st = J.stop()
    if not st then return "none" end
    local leg = J.leg()
    local test = J.isTest()
    local svc = test and "FlightTestService" or "GoalService"
    S.task = (test and __T["Test: "] or __T["Job: "]) .. tostring(st.Progress or st.Do):gsub("%[Tap%]%s*", ""):sub(1, 40)
    if not J.SUPPORT[st.Do] then
        LOG("unsupported stop", st.Do)
        return "unsupported"
    end
    if (st.Do ~= "Plane" and st.Do ~= "Vehicle") and not J.seated() then J.board() end
    if st.Call then if test then M.fire("FlightTestService", "Radio", st.Call) else J.clear(st.Call, st.Call == "AtcTakeoff" and "Takeoff" or (st.Call == "AtcLanding" and "Land" or "Taxi"), 2) end end
    if test and st.Step == "Stall" then M.fire("FlightTestService", "Stall", true) end
    if test and st.Step == "Recover" then
        M.fire("FlightTestService", "Stall", false)
        local _, rr = J.car()
        if rr then
            local look = Vector3.new(rr.CFrame.LookVector.X, 0, rr.CFrame.LookVector.Z)
            if look.Magnitude < 0.01 then look = Vector3.new(1, 0, 0) end
            look = look.Unit
            local p = rr.Position
            J.glide(p, p + look * 300 - Vector3.new(0, 60, 0), 2.5, look)
            J.glide(rr.Position, rr.Position + look * 250, 2, look)
        end
    end
    if type(st.Need) == "table" then
        if test then M.fire("FlightTestService", "Plane", st.Need.Mode or "Cruise", st.Need.Gear == true, st.Need.Lights ~= false) end
        if st.Need.Call then M.fire(test and "FlightTestService" or "FlightRulesService", "Radio", st.Need.Call) end
        if st.Need.Lights then M.fire("CarService", "PlaneLights", true) end
        if st.Need.Engine then M.fire("CarService", "PlaneEngine", true) end
        if st.Need.Gear ~= nil then M.fire("CarService", "PlaneGear", st.Need.Gear) end
    end
    if st.Teach and st.Do ~= "Pass" then
        local try = type(st.Teach.Try) == "table" and st.Teach.Try or {}
        if try.Engine then M.fire("CarService", "PlaneEngine", true) end
        if try.Lights then M.fire("CarService", "PlaneLights", true) end
        task.wait(0.4)
        if test then M.fire("FlightTestService", "Learned", leg) end
    end
    local _, root = J.car()
    if st.Do == "Plane" or st.Do == "Vehicle" then
        J.board()
    elseif st.Do == "Wait" and root and J.seated() and J.agl(root.Position) < 60 then
        local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
        if look.Magnitude < 0.01 then look = Vector3.new(1, 0, 0) end
        local tg = lp:GetAttribute("GoalTarget")
        local p = typeof(tg) == "CFrame" and (tg.Position + Vector3.new(0, J.rootH() - 0.4, 0)) or root.Position
        J.hold(p, look, 20, leg)
    elseif st.Do == "Drive" then
        local tg = lp:GetAttribute("GoalTarget")
        if typeof(tg) == "CFrame" then
            local p = tg.Position + Vector3.new(0, J.rootH() - 0.4, 0)
            J.place(p, tg.LookVector, Vector3.zero)
            J.hold(p, tg.LookVector, 7, leg)
        end
    elseif st.Do == "Takeoff" and root then
        J.takeoff(test)
    elseif st.Do == "Pass" and root and st.At then
        local at = Vector3.new(st.At[1], st.At[2], st.At[3])
        J.glide(root.Position, at, math.clamp((at - root.Position).Magnitude / 220, 0.8, 8))
        if st.Teach then M.fire(svc, "Learned", leg) end
        if st.Then then local th = Vector3.new(st.Then[1], st.Then[2], st.Then[3]) J.place(at, th - at, (th - at).Unit * 60) end
    elseif st.Do == "Fly" and st.GoAround then
        local rw = J.runway(st.To)
        if rw then
            local dir = J.dirOf(rw.Heading)
            local aim = Vector3.new(rw.Aim.X, J.groundY(rw.Aim.X, rw.Aim.Z, rw.Y) or rw.Y, rw.Aim.Z)
            local start = aim - dir * 400 + Vector3.new(0, 70, 0)
            J.place(start, dir, dir * 50)
            task.wait(0.25)
            J.glide(start, aim + Vector3.new(0, 35, 0), 3, dir)
            J.glide(aim + Vector3.new(0, 35, 0), aim + dir * 500 + Vector3.new(0, 140, 0), 3, dir)
        end
    elseif st.Do == "Fly" then
        J.land(st.To, svc)
    elseif (st.Do == "Hover" or st.Do == "Settle") and root then
        local tg = lp:GetAttribute("GoalTarget")
        local at = st.At and Vector3.new(st.At[1], st.At[2], st.At[3]) or (typeof(tg) == "CFrame" and tg.Position) or root.Position
        if st.Do == "Settle" then at = at + Vector3.new(0, J.rootH(), 0) end
        local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
        J.glide(root.Position, at, math.clamp((at - root.Position).Magnitude / 220, 0.6, 6), look)
        J.hold(at, look, (tonumber(st.Seconds) or 4) + 6, leg)
    elseif st.Do == "Dust" then
        M.fire("GoalService", "Dust", leg, 1)
    elseif st.Do == "Act" then
        M.fire("GoalService", "Act", leg)
    end
    local moved = J.waitLeg(leg, (st.Do == "Wait") and 20 or 7)
    if not moved then
        J.bad[leg] = (J.bad[leg] or 0) + 1
        LOG("stuck leg", leg, st.Do)
        return "stuck"
    end
    return "ok"
end
function J.pickJob()
    local ok = M.call("GoalService", "OpenBoard")
    task.wait(0.6)
    local j = J.sheet()
    if not (j and j.Board and j.Rows) then return false end
    local best, bp
    for i, r in ipairs(j.Rows) do
        if not r.Locked and not J.kindBad[r.Kind or ""] then
            local pay = tonumber(r.Pay) or 0
            if picked("j_kinds", r.Kind or "") or not Opt.j_kinds or next(Opt.j_kinds.Value or {}) == nil then
                if not best or pay > bp then best, bp = i, pay end
            end
        end
    end
    if not best then return false end
    local res = M.call("GoalService", "PickJob", best)
    LOG("pick", best, j.Rows[best].Kind, bp, type(res) == "table" and tostring(res.Ok) or tostring(res))
    task.wait(0.8)
    return J.state() == "Active"
end
function J.collectCard()
    local waiting = tonumber(lp:GetAttribute("CardWaiting")) or 0
    local lic = tonumber(lp:GetAttribute("License")) or 1
    if waiting <= lic then return false end
    if J.cardCD and os.clock() - J.cardCD < 20 then return false end
    J.cardCD = os.clock()
    local isl = Workspace:FindFirstChild("Islands")
    local desk = isl and isl:FindFirstChild("PilotDesk", true)
    local clerk = desk and desk:FindFirstChild("Clerk", true)
    if not clerk then return false end
    S.task = __T["Collecting license"]
    if J.seated() then M.call("CarService", "Exit") task.wait(0.8) end
    local cp = clerk:GetPivot()
    local r = M.root()
    if r then r.CFrame = CFrame.new(cp.Position + cp.LookVector * 6, cp.Position) end
    task.wait(1)
    local pr = clerk:FindFirstChildWhichIsA("ProximityPrompt", true)
    if pr and typeof(fireproximityprompt) == "function" then pcall(fireproximityprompt, pr) task.wait(1) end
    local res = M.call("LicenseService", "CollectCard")
    LOG("collect card", type(res) == "table" and (tostring(res.Ok) .. " " .. tostring(res.Reason)) or tostring(res))
    if type(res) == "table" and res.Ok then notify(__T["New license!"]) end
    return true
end
J.islCD = {}
function J.islandTest()
    local os_ = M.json("Outstations")
    if type(os_) ~= "table" then os_ = {} end
    for isl in pairs(J.wantIsl or {}) do if os_[isl] == nil then os_[isl] = { Rated = false } end end
    for isl, v in pairs(os_) do
        if type(v) == "table" and not v.Rated and (not J.islCD[isl] or os.clock() - J.islCD[isl] > 90) then
            J.islCD[isl] = os.clock()
            local islands = Workspace:FindFirstChild("Islands")
            local im = islands and islands:FindFirstChild(isl)
            local ap = D.AP.List and D.AP.List[isl]
            if J.seated() then M.call("CarService", "Exit") task.wait(0.8) end
            local r = M.root()
            if ap and ap.Centre and r then
                r.CFrame = CFrame.new(ap.Centre.X, 60, ap.Centre.Z)
                pcall(function() lp:RequestStreamAroundAsync(Vector3.new(ap.Centre.X, 0, ap.Centre.Z), 5) end)
                task.wait(1)
            end
            local desk = im and im:FindFirstChild("Outstation", true)
            desk = desk and desk:FindFirstChild("Desk")
            if desk and r then
                S.task = __T["Island license: "] .. isl
                local dp = desk:GetPivot()
                r.CFrame = CFrame.new(dp.Position + dp.LookVector * 6 + Vector3.new(0, 3, 0), dp.Position)
                task.wait(1.2)
                local res = M.call("OutstationService", "Book", isl)
                LOG("island test", isl, type(res) == "table" and (tostring(res.Ok) .. " " .. tostring(res.Reason)) or tostring(res))
                if type(res) == "table" and res.Ok then task.wait(1.5) return true end
            end
        end
    end
    return false
end
function J.bookTest()
    local lic = tonumber(lp:GetAttribute("License")) or 1
    local cls = D.LC.Classes and D.LC.Classes[lic + 1]
    if not cls then return false end
    local need = cls.Needs and cls.Needs.Jobs or 0
    local done = tonumber(lp:GetAttribute("LicenseJobs")) or 0
    if done < need then return false end
    if M.cash() < (cls.Fee or 0) then return false end
    if J.testCD and os.clock() - J.testCD < 30 then return false end
    local r = M.call("FlightTestService", "Book", lic + 1, "Reception")
    LOG("book test", lic + 1, type(r) == "table" and (tostring(r.Ok) .. " " .. tostring(r.Reason)) or tostring(r))
    if type(r) == "table" and not r.Ok and type(r.Reason) == "string" then
        for site, ap in pairs(D.AP.List or {}) do
            if ap.Name and r.Reason:find(ap.Name, 1, true) and ap.Stands and ap.Stands[1] then
                local s = ap.Stands[1]
                if not J.seated() then J.board() end
                J.place(Vector3.new(s.X, (s.Y or 0.6) + J.rootH() - 0.4, s.Z), J.dirOf(s.Facing), Vector3.zero)
                task.wait(1.2)
                r = M.call("FlightTestService", "Book", lic + 1, "Reception")
                LOG("book test at", site, type(r) == "table" and (tostring(r.Ok) .. " " .. tostring(r.Reason)) or tostring(r))
                break
            end
        end
    end
    if not (type(r) == "table" and r.Ok) then J.testCD = os.clock() return false end
    task.wait(1.5)
    return true
end
