function U.planes()
    local list = {}
    for id, c in pairs(D.CR.ById or {}) do
        if type(c) == "table" and c.Plane and tonumber(c.Price) and c.Price > 0 then list[#list + 1] = c end
    end
    table.sort(list, function(a, b) return a.Price < b.Price end)
