    local best
    for _, c in ipairs(U.planes()) do
        if (tonumber(c.License) or 99) <= lic and c.Price <= cash and not U.owned(c.Id) and not J.badPlane[c.Id] and c.Role ~= (J.badRole or "") and (not U.fail[c.Id] or os.clock() - U.fail[c.Id] > 60) and U.rank[c.Id] ~= U.isleJobs(c.Island or c.Hangar) and not (U.nosale[c.Id] and os.clock() < U.nosale[c.Id]) then best = c end
    end
    if not best then return false end
    local r = M.call("LicenseService", "Buy", best.Id)
    LOG("buy plane", best.Id, best.Price, type(r) == "table" and (tostring(r.Ok) .. " " .. tostring(r.Reason)) or tostring(r))
    local needIsl = type(r) == "table" and not r.Ok and type(r.Reason) == "string" and r.Reason:match("need the (%w+) License")
    if needIsl then J.wantIsl = J.wantIsl or {} J.wantIsl[needIsl] = true end
    if type(r) == "table" and not r.Ok and type(r.Reason) == "string" and r.Reason:find("for sale") then U.nosale[best.Id] = math.huge end
    if type(r) == "table" and not r.Ok and type(r.Reason) == "string" and r.Reason:find("%d+ more") then U.nosale[best.Id] = os.clock() + 300 end
    if type(r) == "table" and not r.Ok and type(r.Reason) == "string" and r.Reason:find("need rank") then U.rank[best.Id] = U.isleJobs(best.Island or best.Hangar) end
    local where = type(r) == "table" and not r.Ok and type(r.Reason) == "string" and r.Reason:find("Come and see it")
    if where then
        local pos = U.bayOf(best.Id)
        if not pos then
            local isl = best.Island or best.Hangar
            local ap = isl and D.AP.List and D.AP.List[isl]
            if ap and ap.Centre then
                local c = Vector3.new(ap.Centre.X, 10, ap.Centre.Z)
                if J.seated() then M.call("CarService", "Exit") task.wait(0.8) end
                local rr = M.root()
                if rr then rr.CFrame = CFrame.new(c + Vector3.new(0, 50, 0)) end
                pcall(function() lp:RequestStreamAroundAsync(c, 5) end)
                task.wait(1)
                pos = U.bayOf(best.Id)
            end
        end
        if pos then
            S.task = __T["Buying "] .. tostring(best.Name or best.Id)
            if J.seated() then M.call("CarService", "Exit") task.wait(0.8) end
            local rr = M.root()
            if rr then rr.CFrame = CFrame.new(pos + Vector3.new(0, 4, 0)) end
            task.wait(1)
            r = M.call("LicenseService", "Buy", best.Id)
            LOG("buy plane at bay", best.Id, type(r) == "table" and (tostring(r.Ok) .. " " .. tostring(r.Reason)) or tostring(r))
        end
    end
    if type(r) == "table" and r.Ok then notify(__T["Bought "] .. tostring(best.Name or best.Id)) return true end
    U.fail[best.Id] = os.clock()
    return false
end
